// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    // fuzz parameter is the timestamp we will warp to before calling fallback
    function testFuzz_property(uint256 ts) public {
        // keep ts within a reasonable range for block.timestamp
        vm.assume(ts <= type(uint256).max);

        // ensure contract has initial pastBlockTime = 0 (constructor didn't set it)
        // First, perform a successful fallback to set pastBlockTime to some baseline > 0
        address actor = address(this);
        vm.deal(actor, 20 ether);
        // perform an initial successful call at time baseline
        vm.warp(1 hours);
        bool ok;
        // call fallback via low-level call forwarding 10 ether exactly
        (ok,) = address(c).call{value: 10 ether}("");
        require(ok, "initial setup call must succeed");
        uint256 prior = c.pastBlockTime();

        // Now warp to the fuzzed timestamp and attempt the deciding call
        // We don't restrict ts relative to prior; the property must hold for all ts
        // but reference C must revert when ts <= prior
        vm.warp(ts);

        bool decidedOk;
        // The deciding observable behavior is whether the low-level payable call succeeds or reverts.
        // Wrap in try/catch via low-level call to observe success boolean.
        (decidedOk,) = address(c).call{value: 10 ether}("");

        // General rule: reference C must revert (decidedOk == false) whenever block.timestamp <= prior.
        // Since this test runs against the reference C, this must hold for all ts. The mutant that removed
        // the require can succeed (decidedOk == true) for some ts <= prior, so the test will fail on the mutant.
        if (block.timestamp <= prior) {
            assertTrue(!decidedOk);
        } else {
            // when timestamp increased, both should allow the call (so decidedOk should be true)
            assertTrue(decidedOk);
        }
    }
}
